def add(id,range,targets,duration,conc,resolution,effect,limits,notes,scaling='None.'):
 s=src[id];cards.append({'id':id,'activation':'Action','rangeFeet':range,'targets':targets,'duration':duration,'concentration':conc,'components':['V','S','F'],'resolution':resolution,'effect':effect,'scaling':scaling,'limitations':limits+common,'designNotes':notes,'implementationStatus':'LOCAL CANDIDATE — source-reconciled; exact manuscript review pending; not selectable','sourceCoreEntries':s['sourceCoreEntries'],'sourcePlacements':s['sourcePlacements'],'classAccessEvidence':s['classAccess'],'sourceReview':[review],'reviewEvidence':[]})

add('summon-earth-pet',60,'One unoccupied space you perceive within range and line of effect.','Concentration, up to 1 minute. '+minute+' Ends earlier at concentration end or pet 0 HP.',True,
 'No initial roll. Its commanded offensive Action makes one melee spell attack using your actual casting-class spell attack bonus, reach 5 feet. A hit deals 1d10 bludgeoning, with no ability damage modifier. After that hit, a Large-or-smaller target makes a Strength save against your spell DC; failure makes it Prone. A successful save prevents only knockdown. Ordinary attack, critical and defense rules apply.',
 'Summon one Medium earth elemental companion: AC17, HP30, walking Speed30, body mass300 pounds, saves equal to owner PB, other checks +0, ordinary sight/hearing. It understands your spoken commands but has no speaking language or telepathy. It acts immediately after you. Your Bonus Action, while within60 feet and able to convey a perceived command, permits movement plus its attack or one basic legal nondamaging Action. Without a command it may move defensively and Dodge. The attack consumes the owner-wide one offensive companion Action for that numbered round even on a miss; it shares the owner-wide command allowance.',
 'Huge/Gargantuan targets take damage normally but are ineligible for this knockdown unless an exact rule overrides that size gate. Prone immunity or an exact immunity expressly covering knockdown prevents Prone; immunity only to positional push/pull does not itself grant Prone immunity. Damage reduced to0 does not erase a resolved hit or its separate save. Knockdown supplies no displacement, collision damage, stun or whole-Action denial; ordinary support/Falling and stand-up rules apply. One Earth Pet per caster; it vanishes at0HP or concentration end. No burrow, tremorsense, earth glide, resistance, immunity, hands/tool use, cargo capacity, free Help advantage, autonomous opportunity attack, spellcasting, loot, corpse or resource/death trigger. Its printed mass is real for carrying and condition accounting but cannot be harvested as permanent stone.'+replace,
 'PRESERVED: Action/60feet/V,S,F/concentration1minute, AC17/HP30/1d10 bludgeoning plus knockdown. NEW: Medium/300lb/Speed30, finite companion interface, spell attack and STR-save knockdown capped at Large. Exact-card clarification distinguishes positional forced-movement immunity from an explicit knockdown/Prone immunity.',
 'Only the printed owner PB saves and actual class spell attack/DC change with the caster. AC17, HP30, 1d10 damage and one attack remain fixed; no standard S-dice progression.')

add('conjure-elemental-lance',30,'Every creature, including allies, within one 30-foot-long, 5-foot-wide, 5-foot-high line beginning at the edge of your space; exclude your origin. Choose its direction before resolving it.','Instantaneous',False,
 'Each affected creature makes a Dexterity save against your spell DC. Choose acid, cold, fire, lightning or thunder at casting and roll one shared4d6. Failure takes full rolled damage; success takes floor(total/2); then apply each target\'s ordinary defenses.',
 'On a5-foot grid the line occupies six contiguous squares in one straight direction. Resolve a creature only once even if it occupies multiple affected squares. Total cover from the origin excludes the creature; intervening creatures do not independently stop the line. The elemental lance exists only for this instantaneous damage resolution.',
 'This is an area save, with no attack roll, critical hit, ability damage modifier, persistent weapon, object damage, ignition, chain, push, slow or terrain effect. The caster cannot omit allies merely by calling the line selective.',
 'PRESERVED: Action/30-foot line/V,S,F/instantaneous,4d6 elemental damage and save-half. NEW: five-element choice, DEX save, bounded line cross-section, all-creature selection, shared roll and one resolution per creature.')

add('burst-of-flamewind',15,'Creatures at known locations in a15-foot cone that you designate as enemies from ordinary information before resolution. Choose the cone orientation before selecting its targets; you may select some or all eligible creatures.','Instantaneous',False,
 'Each selected creature takes the same shared roll of3d8 fire damage automatically, subject to ordinary defenses. It then makes a Strength save against your spell DC. Failure pushes it5feet directly away from you; success prevents only this push. Fire immunity does not itself prevent the save or displacement.',
 'The cone begins at the edge of your space, extends15feet and has diameter equal to distance from the origin, reaching15feet across at its far end; your origin is excluded. On a grid, include a creature if the center of at least one occupied square lies within the cone footprint, including its boundary; resolve it only once. Use actual height and the same cone volume for airborne creatures. Total cover from the origin excludes a creature. A creature\'s location can be known without being visible, but the spell never finds an unknown location or identifies hidden allegiance.',
 'The push follows ordinary forced movement: no ordinary opportunity attack, no Speed expenditure, stop at a solid obstacle or illegal occupied space, no collision damage or automatic Prone. Existing Brace may reduce it under its own rules. No generic size cap is added; explicit immovability or applicable forced-movement immunity applies. After movement resolve actual support/Falling normally; pushing a flying creature does not itself remove its flight. Enemy designation does not establish moral truth, reveal disguise, change factions or create a magical hostility detector. No object damage, lasting wind, ignition, Burn or other fire rider.',
 'PRESERVED: Action/15-foot cone/V,S,F/instantaneous, selective enemies,3d8 fire and5-foot push. NEW: automatic damage plus STR save for push only, ordinary-information target designation, shared roll, finite cone and grid inclusion rule. Automatic selective damage at rank3 remains a future numerical-balance question.')

add('elemental-displacement',5,'Yourself or one willing ally you perceive within5feet and line of effect. Choose one unoccupied destination you perceive within30feet of that recipient.','Instantaneous',False,
 'No roll. At resolution confirm the willing recipient remains eligible and the destination is within30feet of its then-current position and can legally contain its whole body. Teleport the recipient and its legal noncreature belongings atomically. If a required condition or exact teleport ward prevents this, no movement occurs and paid cast costs remain spent.',
 'Worn, held and carried noncreature property in lawful physical custody travels with the recipient, including legally melded possessions under the existing body/equipment rules. The recipient must satisfy its actual carrying and anatomy rules; the spell creates no extra capacity or free equipment transfer. No other creature travels with it: neither a grappled target, carried body, passenger nor mount. Such a creature remains at the origin with its own actual custody and position; ordinary lost support or released grapple consequences then apply. The recipient traverses no intervening terrain, spends no Speed and provokes no ordinary opportunity attack. Speed0 alone does not prevent teleportation.',
 'The caster must perceive the arrival space, but no clear physical path or line of effect through the intervening terrain to that destination is required; this explicit destination exception permits teleporting past a visible transparent barrier, subject to exact wards. Direct selection of an allied recipient still requires5feet and line of effect. Arrival in unsupported open space is legal if the body fits; ordinary Falling begins if it lacks actual flight/hover/support. A blocked, occupied or otherwise illegal arrival fails without splitting bodies, dropping selected gear, damaging matter or finding a different square. No residual portal, planar travel, attack, action, RP refresh, clock reset or return trip is granted.',
 'PRESERVED: Action/V,S,F/instantaneous and teleport self or ally30feet. CONFLICT RULING: raw Core Self range is retained as evidence; NEW5-foot willing ally selection makes the printed ally option usable. NEW: explicit perceived-destination path exception, atomic custody/creature exclusions and unsupported-arrival/Falling procedure.')

add('summon-spectral-steed',60,'One unoccupied space you perceive within range and line of effect large enough to contain the mount.','Concentration, up to1minute. '+minute+' Ends earlier at concentration end or steed0HP.',True,
 'No creation roll. A commanded Planar Crossing uses the steed\'s Action and its one crossing attempt. Spend that use when the attempt starts. It teleports the steed, any eligible mounted rider and permitted gear together to a specific known site on another plane, or fails safely at origin if arrival is illegal or an exact ward blocks it. Failure does not refund the attempt or actions and reveals no reason or hidden coordinates.',
 'Create a Large noncombat spectral mount: AC14, HP30, walking Speed60, body mass500pounds, saves equal to owner PB, other checks+0, ordinary sight/hearing; it understands the owner\'s spoken commands without speech or telepathy. It acts immediately after the owner. An owner Bonus Action command within60feet and perceptible to it permits movement plus Dodge, Dash or Planar Crossing; Dash uses the ordinary movement-budget rules. It shares the owner-wide companion command allowance but supplies no damaging Action. Uncommanded it may move defensively and Dodge. It may carry one willing Medium-or-smaller rider plus that rider\'s legally carried noncreature gear, within350pounds AND12Load total. Count the rider\'s effective body weight plus every item once; count body casualty Load (Tiny1.5/Small3/Medium6) plus all gear Load, including melded gear. At6–12Load it is Burdened under BODY_EQUIPMENT_PLAYTEST.md: Speed reduced10feet and relevant check disadvantage. These fixed capacities do not imply a Strength score. Mounting requires an Action while adjacent to the stationary steed and within both capacities. Dismounting voluntarily requires an Action while it is stationary, to a legal adjacent space; this Action includes that placement. While riding, select one5-foot portion of the steed\'s footprint as the rider\'s position; it moves with that portion, without free repositioning among its squares. Other positioning requires actual legal movement/actions. If the steed disappears or the rider can no longer legally ride, the rider remains at their current rider position and ordinary support/Falling applies; use the body guide\'s minimum adjacent placement rule if a persistent steed/obstruction makes that position illegal, never teleport through a barrier. An imposed excess load or anatomy change cannot be vetoed to preserve riding.\n\nFor Planar Crossing, the owner chooses one specific arrival site on a different plane that they personally visited or can uniquely identify from a reliable map, description or established source. The command authorizes the attempt; the steed spends its Action after the owner. A mounted rider must still willingly accept and fit the capacity/anatomy rules. An unladen steed may also cross. Arrival needs legal space for the whole mount and rider; ordinary support requirements apply, so unsupported arrival leads to Falling rather than hover. Distance to the destination is not limited by the60-foot summoning/command range. The spell provides the interplanar transition itself without requiring an existing portal, but no same-plane teleport. The group moves atomically, preserving relative rider position, belongings, conditions and ongoing clocks. Nothing is left in a between-planes buffer. No portal remains for followers.',
 'One Spectral Steed per caster; one crossing attempt per steed. Resummoning requires a new legal paid cast and new mounting/commands, never a free refresh. This profile grants no attack, autonomous opportunity attack, Help advantage, flight, hover, phase movement, special senses, resistance/immunity, spellcasting, sale value, loot, corpse or resource trigger. It cannot carry a second creature or independent casualty inside a bag, nor substitute cargo-only hauling for the printed rider-and-gear role. No additional carrying capacity, gear ownership change or magical location search is supplied. Its known destination need not be visible or in originating line of effect; the explicit interplanar exception is still subject to actual arrival legality and written blockers. The command must be valid at attempt start; crossing itself does not cancel that already committed command because distance/plane then changes. Future commands require their own actual range/perception. Concentration is not given an extra plane/range tether; clocks continue. Dismissal does not return or delete riders/property. Travel may avoid a geographic route segment but does not settle claims, contamination, law, Opening time or Extraction by declaration.'+replace,
 'PRESERVED: Action/60feet/V,S,F/concentration1minute and a mount that truly travels between planes. NEW: complete finite mount/riding/command/crossing profile and one attempt, known-site eligibility and atomic custody. CORRECTION PROPOSED FOR EXACT REVIEW: source conference proposed6Load, but reviewed BODY_EQUIPMENT_PLAYTEST.md assigns a Medium transported body6Load before equipment. Use12Load total with unchanged350lb ceiling, counting the body and applying ordinary Burdened at6Load. This explicitly changes the NEW proposal to support the promised rider plus gear; it is not a source-derived number. All fixed profile values require human balance review.',
 'Only its expressly printed owner-PB saves change. Fixed AC14/HP30/Speed60 before ordinary burden/conditions,350lb/12Load capacity and one crossing do not automatically scale.')

add('resonance-conduit',60,'Two distinct willing creatures with actual RP pools, each perceived within60feet and line of effect. You may be one participant. Each participant must be free of another active Resonance Conduit.','Concentration, up to1minute. '+minute+' Ends earlier with concentration or either participant willingly ending the link.',True,
 'Automatic link creation, no RP transfer from the casting itself. Either participant may spend an Action to transfer a positive integer of existing RP to the other while both are on the same plane, within60feet of one another and have line of effect. At transfer start the recipient must accept; choose an amount no greater than donor currentRP or recipient currently missingRP. Commit the Action and immediately deduct that amount from the donor. At resolution credit the same amount, capped at recipient actual maximumRP; any newly excess amount is lost.',
 'The two creatures retain separate RP pools and maxima. Deducted pendingRP is not spendable by either party and cannot be committed again; only a completed credit enters the recipient\'s pool. At resolution the link and recipient acceptance must still exist and same-plane/range/line-of-effect gates must still hold. If an exact interrupt or loss of these conditions prevents the transfer after commitment, its RP and Action are not refunded. Ordinary movement outside the transfer gate suspends permission without ending the link or pausing duration; returning restores only future permission. Either participant may voluntarily end the whole link without an Action, including before agreeing to a new conduit; ending one participant\'s link releases both, but never reverses completed or committed transfers. The caster can maintain only one conduit and each participant can belong to only one at a time.',
 'The original cast pays its own5RP base cost and applicable surcharges before the link exists; future transfer cannot finance it retroactively. Transferring is not casting, recovery from rest or creation of RP. Casting/Dissonance/Refrain/resource-generation hooks do not apply unless an exact feature expressly names Conduit transfer. No joint maximum, discounts on the transfer amount, overflow store, negative balance, duplicate credits, borrowed casting rights, simultaneous double spending, future recovery, HP, charges or materials. Copies cannot duplicate transfers or create spendable RP. No daily limit is added; named recovery ledgers, Dissonance, Refrain, actions and clocks remain unchanged. Suppression prevents transfer while applicable without pausing the endpoint; it never refunds a committed transfer. New consent/recasting cannot reinstate an ended link.'+replace,
 'PRESERVED: Action/60feet/V,S,F and RP sharing between allies. CONFLICT RULING: Core Instantaneous metadata becomes a NEW finite1minute concentration permission rather than an indefinite shared pool. NEW: two participants/one link each, Action transfer, actual-pool conservation,60foot same-plane/line-of-effect gate, commitment/no-refund timing, current-cap clipping and explicit participant withdrawal.')

add('faction-portal',60,'One legal open local entrance space you perceive within60feet and line of effect, on suitable ground. Choose one exact canonical factionId with a recorded current reputation score above0 and one specific known headquarters of that faction.','Concentration, up to1minute. '+minute+' Ends earlier if concentration ends.',True,
 'No roll. On successful casting create one visible, fixed, one-way doorway5feet wide and8feet high. The destination is a known established public/default receiving point for the chosen headquarters, or, absent such a point, one specific known ordinary primary entrance/foyer. Identify it from personal experience or reliable public information; no existing portal infrastructure is needed. It may be on the same or another plane. Recheck each actual crossing against legal arrival space and exact teleport/planar blockers; failure leaves the crossing creature and belongings at the local entrance, with no split or deletion.',
 'Any creature that physically fits the entrance under ordinary anatomy/squeezing rules may use it; passengers need no positive reputation or faction membership. Entering costs5feet of ordinary movement, subject to ordinary movement-cost adjustments, and atomically transports that creature and its legally carried belongings to a legal unoccupied space at or adjacent to the chosen receiving point. Ordinary carried creatures may accompany it only within the carrier\'s actual anatomy, pound and Load capacity and with room for the whole arriving group; this does not create willing-target immunity against being actually carried. Choose the receiving point when casting and keep it fixed. At each crossing use the nearest legal space at/adjacent to that point that fits the whole group, with a fixed neutral board order for ties, never a tactical remote choice or search through barriers. If none exists, the crossing fails and the attempted movement remains spent. Ordinary approach movement can provoke opportunity attacks; the teleport transition itself cannot. Items carried through remain the same items with actual ownership, contents, conditions and provenance. Loose unattended objects do not independently activate transit: a creature must physically carry or legally handle them as part of its own crossing; thrown projectiles, remote pushes and spells cannot deliver goods through by themselves.\n\nThe doorway is opaque to sight and sound and supplies no line of effect through it. Attacks, spells, areas, projectiles and remote sensing do not pass. There is no exit doorway or automatic return route. Complete a currently resolving legal crossing atomically before closing/suppressing the doorway; expiry never bisects a body or cargo. Later crossings require the still-active doorway. Suppression makes it unusable without pausing its endpoint. It has no physical HP, support or barrier body; when inactive there is no active transit surface. One portal per caster; a successful replacement closes the old one. Current positive reputation is checked as a creation gate at cast start and resolution, not a continuing passenger credential; a later standing change does not itself close a created portal.',
 'Use the actual canonical reputation record: positive means above0, normally+1 through+3 under REPUTATION.md; missing/0/negative standing fails the gate. This card does not replace that scale with the historical Gameplay Loop\'s -5..+5 scale. No faction membership, Seal invocation permission, headquarters infrastructure or automatic entry authorization is added. If there are several HQs, select exactly one known site; no hidden vault, secret room, unknown HQ, location search or knowledge report. The far endpoint needs no originating line of sight/effect and has no geographic range ceiling, but actual wards and legal placement still apply. A headquarters that ceases to exist or belong to the faction cannot receive new crossings; a purely clerical name change does not move the chosen physical point. Failed crossings reveal no cause beyond failure, although ordinary observers may draw inferences. The spell can bypass a geographic route leg and deliver people to Haven when that actual HQ is there. It never automatically completes Extraction, advances or resets the Opening clock, settles cargo claims, removes contamination, changes ownership/reputation, grants credentials, ignores guards/laws/taxes or refunds cast costs. No free actions, additional capacity, object duplication or attacker path across planes.'+replace,
 'PRESERVED: Action/60feet/V,S,F, doorway to a faction headquarters with positive reputation, actual planar travel supported by Planar tag. CONFLICT RULING: Core Instantaneous metadata becomes NEW1minute concentration for a usable doorway. NEW: known ordinary receiving-site procedure, fixed one-way5x8ft entrance, local5foot movement cost, whole-group atomic arrival, opaque transport-only interface, any-passenger use, no later reputation tether and exact destination legality. Canon positive predicate is retained without silently changing the reputation scale; route bypass remains possible while actual settlement procedures persist.')

assert len(cards)==7
def readable(text):
 text=re.sub(r'(?<=[A-Za-ce-zA-CE-Z])(?=\d)', ' ', text)
 text=re.sub(r'(?<=\d)(?=(?![dx]\d)[A-Za-z])', ' ', text)
 return text.replace('shared4d6','shared 4d6').replace('shared-roll3d8','shared-roll 3d8')
for card in cards:
 for field in ['targets','duration','resolution','effect','scaling','limitations','designNotes']:
  card[field]=readable(card[field])
candidate={'status':'LOCAL CANDIDATE — SOURCE-RECONCILED; exact manuscript review pending; NOT SELECTABLE','scope':'Seven rank-3 Conjuration identities; seven original placements/Core blocks and actual seven-class access preserved. Authored tabletop procedures; effect runtime, numerical balance and whole-game closure remain open.','reviewEvidence':[review],'spells':cards}
p=D/'candidate_conjuration_rank3.json';p.write_text(json.dumps(candidate,indent=2,ensure_ascii=False)+'\n',encoding='utf-8');digest=hashlib.sha256(p.read_bytes()).hexdigest()
intro='''# Seven rank-3 Conjuration spells — exact manuscript review

Please review every exact card below against the source conference and shared rules. Approve or state exact required repairs before promotion. Catalog remains152/696 until approval. All seven original placements/Core blocks and actual class-access rows are preserved. This request is for authored tabletop manuscript approval, not runtime, numerical balance or whole-game closure. Please keep response under16,000characters.

Several concrete interface decisions require your review:

1. Earth Pet: distinguish Prone/knockdown immunity from mere positional push/pull immunity. Prone has no displacement here, so generic push immunity alone should not cancel it. Damage0 still leaves the hit/save. Source conference's phrase 'forced-movement immunity' is narrowed to any exact immunity actually covering knockdown. Confirm this clarification or give precise replacement.
2. Lance preserves your six-square line. Flamewind preserves source automatic3d8 damage, STR-save push only and enemy choice. Its exact cone has diameter equal to distance (15ft long/15ft far width), grid-square-center inclusion/boundary counts/once per creature. No magic hostility/unknown-location detector; known but unseen location can be selected. This is explicitly NEW exact geometry, not a claim all general templates reviewed.
3. Displacement: perceived destination has no requirement for unobstructed intervening LoE/path (can see through transparent wall and teleport), while allied recipient needs5ft/LoE. This makes actual teleport useful and matches the source conference's separation. Destination must be legal/perceived and within30ft of recipient at resolution. Noncreature belongings travel under real custody/capacity; other creatures remain at origin. No planar travel.
4. STEED CAPACITY CONFLICT FOUND IN FILES: your proposed6Load total is already fully consumed by a Medium rider's casualtyLoad6 before gear. BODY_EQUIPMENT_PLAYTEST.md lines94–111 requires both body casualtyLoad and gear when carrying another creature (table below). The exact card therefore proposes NEW12Load total with unchanged350lb, counts rider body/gear/meld once, and applies ordinary Burdened threshold6Load (base60 becomes50). This supports one Medium rider plus up to6Load gear subject to actual pounds, without pretending12 is source-printed or changing existing carrying rules. Please approve this explicit correction or give a usable alternate. Profile has no inferredSTR. Rider mount/dismount Action, chosen5ftportion moves with mount, no free reposition; loss/forced overload invokes ordinary local placement/Falling, never deleting or vetoing imposed condition. Steed acts after owner, command at attemptstart sufficient for committed crossing; later commands still need actualrange/perception. One attempted real interplanar crossing per steed, no same-plane teleport, legal known-site requirement allows no-infrastructure journey; unsupported legal arrival follows Falling. Can cross unladen; no cargo-onlyhauling role/extra body hidden inbag.
5. Conduit: source conference left postcommit capacity/gate timing implicit. Exact card holds deductedRP pending/unspendable then caps credit at actualrecipientmaximum; surplus lost. Recheck active link/consent/plane60ftLoE atresolution, prevent=>no refund. Leaving range suspends only permission while link clock keepsrunning, returning noresource refresh. Participant may endwholelink withoutAction; this frees both endpoints but refunds neither completed norpendingtransfer. Copiescannot duplicateRP. No new daily cap.
6. Portal: source conference quoted historicalGameplayLoopscale -5..+5, but REPUTATION.md playablecanon remains normally-3..+3, as used in earlier reviewedFactionEmblem. Exactpredicatepositive>0 is compatible; cardexplicitlydoesnotmigratescale. Entrance5x8onactualgroundfixed, one-wayopaque transport, anyphysicalpassenger withordinarycapacity. KnownHQ public/defaultpoint orordinaryprimaryentrance/foyer; no secret-locationoracle/infrastructuregate. Same-planeorinterplanar, no distantLoErequirement. Recipientspace nearestlegalat/adjacent tofixedpoint, neutralorder ties/no remotetacticalchoice; fullcarriedgroupmustfit. Ordinarycarriedcreaturesallowed unlikeDisplacement'sexplicitexclusion. Loosegoods requireactualcreaturetransport;no remoteprojectile/attack/spellthrough. Transitspends5feetordinarymovementcost(subjecttosqueezeetc);failedattemptstillspent. Finishthecurrentlyresolvingcrossingatomicallybeforeclosure;latercrossingsneedactiveportal. Checkpositiveatcaststartandresolution, notongoingstandingtether. ActualHQ no longerexists/belongstofactionblocksnewcrossing;pointdoesn'tchasechangingHQ. Sourceabilitycanbypassgeographicroute, notpretendthesourceforbidsrealarrivalatHaven; actual settlement/clocks/cargo remain.

If approved I will integrate only these bounded travel/carrying/RP-transfer interfaces, keep the larger travel/mount/extraction/faction domains open, rebuild spell indices and verify source/access/hash/rendered preservation. Please explicitly identify any conditional approval and required exact changes.

## Existing body/carrying and reputation evidence

'''
for file,spans in [('BODY_EQUIPMENT_PLAYTEST.md',[(94,111),(123,125)]),('REPUTATION.md',[(1,12)])]:
 lines=(R/'docs/mechanics'/file).read_text(encoding='utf-8').splitlines();intro+='\n'+file+'\n'+ '\n'.join(f'{i+1}: {lines[i]}' for lo,hi in spans for i in range(lo-1,min(hi,len(lines))))+'\n'
packet=intro+f'\n## Exact candidate\n\nCandidate byte SHA256: `{digest}`\n\n```json\n'+json.dumps(candidate,indent=2,ensure_ascii=False)+'\n```\n'
pp=A/'CODEX_CONJURATION_RANK3_EXACT_REVIEW.md';pp.write_text(packet,encoding='utf-8')
sub={'status':'prepared for exact manuscript review; not promoted','ids':list(src),'candidatePath':str(p),'candidateSha256BeforeReview':digest,'packetPath':str(pp),'packetSha256':hashlib.sha256(pp.read_bytes()).hexdigest(),'operationalBefore':152,'unfinishedBefore':696}
(A/'CONJURATION_RANK3_EXACT_SUBMISSION.json').write_text(json.dumps(sub,indent=2)+'\n',encoding='utf-8');print(json.dumps({'candidateCards':7,'packetCharacters':len(packet),'candidateSha256':digest},indent=2))
